 /// ⏱️ Quotes the exact work of the next capture, binding, reservation, seed, publication or child action.
 pub fn advance_work_demand(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<u64,ValueError>{if let Some(work)=self.action.work{return Ok(work)}if self.authority.as_ref().ok_or_else(invalid)?.inspect(|producer|producer.identity().is_none()){return Ok(1)}if self.binding.is_none()&&!F::BORROWED{return input.binding_work_demand(&self.binding)}if !self.receiver.reserved(){return Ok(self.receiver.reserve_work_demand())}if !self.receiver.initialized(){return Ok(self.receiver.seed_work_demand())}let receiver=self.receiver.get().ok_or_else(||ValueError::invariant("get target absent"))?;if receiver.output_ready(){return receiver.take_work_demand()}receiver.advance_work_demand(input,body)}
