 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}semio_framework_value_native_receiver_protocol::native_output_demand::<T>(0)}
 /// ⏱️ Quotes the selected actual output publication work.
 pub fn take_work_demand(&self)->Result<u64,ValueError>{self.take_demand().map(|_|1)}
 /// 📤️ Publishes without returning an unowned child across a producer boundary.
 pub fn take(&mut self,output:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{if !self.ready(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}semio_framework_value_native_receiver_protocol::native_output_take(&mut self.output,output,0,effect)}
